   if(dr.tier&&dr.tier!=="none"){const mid=((c.tiers||["A","B","C","D"]).length-1)/2,tv=p=>p.t==null?mid:p.t;for(let i=0;i<T.length;i+=2){const A=T[i].m,B=T[i+1].m,v=[...A,...B].map(tv);x+=dr.tier==="within"?(Math.max(...v)-Math.min(...v))*6:Math.abs(tv(A[0])+tv(A[1])-tv(B[0])-tv(B[1]))*5}}
